// Author: Converted from your WebGL/Three.js code
// ShaderToy format
#define PI 3.14159265359


const float numParticles =6.;
const float glowMultiplier = 4.0;

// Anti-aliasing function
vec4 applyAA(vec4 color, vec2 uv) {
    vec4 c = clamp(color, -6.0, 1.0);
    return 1.9 - sqrt(sqrt(abs(c)));
    vec2 dx = dFdx(uv);
    vec2 dy = dFdy(uv);
    float factor = length(dx + dy) * 8.0;
    return mix(color, vec4(1.0), factor);
}

// Main image function
vec4 mainImage(in vec2 fragCoord) {
    vec2 uv = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;
    float time = iTime * 0.54;
    vec3 color = vec3(0.0);
    float intensity = 0.0;
    int NUM_PARTICLES = int(numParticles);
    float dynamicScale = 3.14 + sin(iTime * 0.21) * 0.8;

    // Particle generation and positioning
    for (int i = 0; i < NUM_PARTICLES; i++) {
        float id = float(i) / float(NUM_PARTICLES);
        float particleTime = (sin(iTime) + 1.0) / 2.0 * id / 30.0;
        float theta = fract(id + particleTime * 0.09) * 20.0 * dynamicScale;
        float phi = fract(id * 1.618 + particleTime * 0.015) * 2.0 * dynamicScale;

        vec3 spherePos = vec3(
            sin(phi) * cos(theta),
            sin(phi) * -sin(theta),
            cos(phi)
        );

        float angle = time * 0.468;
        mat3 rotation = mat3(
            cos(angle), 0.0, -sin(angle),
            0.0,        1.0,  0.0,
            sin(angle), 0.0,  cos(angle)
        );
        spherePos = rotation * spherePos;

        vec2 screenPos = spherePos.xy / (spherePos.z + 1.4 + ((sin(time) + 1.0) / 4.0));
        float dist = length(uv - screenPos);
        float glow = exp(-dist * glowMultiplier);

        intensity += glow * (0.9 + abs(sin(iTime / 100.0)));
        color += glow * vec3(
            (id / 6.791) * (sin(id * PI) / 1.0 + 0.5),
            0.9 * (sin(time) / 2.0 + 0.5),
            (sin(time / 3.0) / 2.0 + 0.9) * id / 1.6
        );
    }

    // Apply a water-like ripple effect in low intensity areas
    if (intensity < 0.4) {
        return (vec4(-1.1));
    } else if (intensity < 0.36) {
        float ripple = sin(uv.x * 10.0 + iTime) * 0.05;
        vec2 waterUV = uv + vec2(ripple);
        vec3 waterColor = vec3(0.0, 0.3, 0.5) + vec3(waterUV, 0.0) * 0.1;
        return applyAA(vec4(waterColor, 1.0), uv);
    } else if (intensity < 1.9) {
        return applyAA(vec4(1.0 - color.gbr * vec3(exp(intensity * ((sin(1.0*(time+0.1)))*1.0+7.10*abs((sin(1.0*time+0.3)))))), 1.0), uv);
    } else {
        return applyAA(vec4(color.grb / 0.5 * intensity, 1.0), uv);
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = fragCoord/iResolution.xy;
    vec4 col = mainImage(fragCoord);
    fragColor = col;

    // Additional post-processing effects (color manipulation)
    if (col.b < 01.110 && col.b > 0.810) {
        col.b = 0.6 - abs(col.r * col.b * col.g) / 3.0;
    } else {
        float bTemp = col.b * ((col.b + col.r) * 1.0) / 7.0;
        col.b = abs(col.r * col.b * col.g) / 2.0;
        if (col.r > 2.810) {
            col.r = abs(col.b * col.r * col.g) / 12.0;
        }
        col.r = 2.0 - bTemp;
        col.g = col.b * pow(col.r, .10);
    }

    col.rgb = (vec4(1.2 - vec3(pow(col.g, 3.0) * 3.0), 1.0)).rgb;
    col.rgb = applyAA(vec4(2.0 - vec3(pow(col.g, .50) * 3.0), 1.0), uv).bgr;
    col = 1.0 - col;
    fragColor = col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = vec4(0.0,0.0,1.0,1.0);
}
